rust.formatting.rs:
pub fn format_tag_counts(unique_count: usize, duplicates: usize) -> String {
    format!("unique={unique_count},duplicates={duplicates}")
}

rust.main.rs:
mod formatting;
mod normalization;

use formatting::format_tag_counts;
use normalization::normalize_tag;
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let mut duplicates = 0;
    for _ in 0..count {
        let tag = lines.next().unwrap().to_string();
        let normalized = normalize_tag(&tag);
        if seen.contains(&tag) { duplicates += 1; } else { seen.insert(tag); println!("{normalized}"); }
    }
    println!("{}", format_tag_counts(seen.len(), duplicates));
}

rust.allocation.rs:
pub fn can_accept(used: i64, units: i64, capacity: i64) -> bool {
    used + units <= capacity
}

rust.formatting.rs:
pub fn format_capacity(used: i64, deferred: i64) -> String {
    format!("used={used},deferred={deferred}")
}

rust.main.rs:
mod allocation;
mod formatting;

use allocation::can_accept;
use formatting::format_capacity;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let capacity: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut used, mut deferred) = (0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let units: i64 = parts.next().unwrap().parse().unwrap();
        if can_accept(used, units, capacity) { println!("{id}:accept"); } else { println!("{id}:defer"); deferred += 1; }
        used += units;
    }
    println!("{}", format_capacity(used, deferred));
}
